script:
frappe.ui.form.on('Employee Checkin', {

    refresh(frm) {

        // =====================================================
        // CHECK-IN NOW BUTTON
        // =====================================================
        if (frm.is_new() && frappe.user.has_role("Employee")) {

            frm.add_custom_button('Check-in Now', function () {

                frm.set_value('log_type', 'IN');
                frm.set_value('time', frappe.datetime.now_datetime());

                frm.save().then(() => {
                    frappe.show_alert({
                        message: 'Check-in recorded successfully.',
                        indicator: 'green'
                    });
                });

            }).addClass('btn-primary');
        }

        // ── Alert: Not yet checked out ──
        if (frm.doc.time && !frm.doc.checkout_time && !frm.doc.__islocal) {
            frm.dashboard.set_headline_alert(
                'Employee has not checked out yet.',
                'orange'
            );
        }

        // ── Show Working Hours ──
        if (frm.doc.time && frm.doc.checkout_time) {
            let checkin  = new Date(frm.doc.time);
            let checkout = new Date(frm.doc.checkout_time);
            let diff     = checkout - checkin;
            let hours    = Math.floor(diff / 1000 / 60 / 60);
            let minutes  = Math.floor((diff / 1000 / 60) % 60);

            frm.dashboard.set_headline(
                `Working Hours: ${hours} hour(s) ${minutes} minute(s)`
            );
        }

        // ── Lock check-in fields after first save ──
        if (!frm.is_new() && frm.doc.time) {
            frm.set_df_property('time',     'read_only', 1);
            frm.set_df_property('log_type', 'read_only', 1);
        }

        // ── Lock all fields after checkout ──
        if (!frm.is_new() && frm.doc.checkout_time) {
            frm.set_df_property('time',         'read_only', 1);
            frm.set_df_property('log_type',     'read_only', 1);
            frm.set_df_property('checkout_time','read_only', 1);
            frm.set_df_property('log_type_out', 'read_only', 1);
        }

        // ── Checkout Now Button ──
        if (!frm.is_new() && frm.doc.time && !frm.doc.checkout_time) {

            frm.add_custom_button('Checkout Now', function () {

                let checkin_time = new Date(frm.doc.time);
                let now          = new Date();
                let diff_hours   = (now - checkin_time) / 1000 / 60 / 60;

                if (diff_hours < 8) {

                    let remaining_minutes = Math.ceil((8 - diff_hours) * 60);
                    let remaining_hours   = Math.floor(remaining_minutes / 60);
                    let remaining_mins    = remaining_minutes % 60;

                    frappe.msgprint({
                        title: 'Checkout Not Allowed Yet',
                        message:
                            `You can only checkout after <b>8 hours</b> from check-in.<br><br>` +
                            `Check-in Time : <b>${frm.doc.time}</b><br>` +
                            `Time Remaining: <b>${remaining_hours} hour(s) ${remaining_mins} minute(s)</b>`,
                        indicator: 'red'
                    });
                    return;
                }

                let now_str = frappe.datetime.now_datetime();
                frm.set_value('checkout_time', now_str);
                frm.set_value('log_type_out',  'OUT');

                frm.save().then(() => {
                    frappe.show_alert({
                        message: 'Checkout recorded successfully.',
                        indicator: 'green'
                    });
                });

            }).addClass('btn-primary');
        }
    },

    checkout_time(frm) {

        if (!frm.doc.time || !frm.doc.checkout_time) return;

        let checkin  = new Date(frm.doc.time);
        let checkout = new Date(frm.doc.checkout_time);

        if (checkout <= checkin) {
            frappe.msgprint({
                title: 'Invalid Checkout Time',
                message: 'Checkout Time cannot be before or equal to Check-in Time.',
                indicator: 'red'
            });
            frm.set_value('checkout_time', '');
            return;
        }

        let diff_hours = (checkout - checkin) / 1000 / 60 / 60;
        if (diff_hours < 8) {
            frappe.msgprint({
                title: 'Checkout Too Early',
                message: 'Checkout is only allowed after 8 hours from Check-in.',
                indicator: 'orange'
            });
            frm.set_value('checkout_time', '');
            return;
        }
    },

    employee(frm) {

        if (!frm.doc.employee || !frm.doc.__islocal) return;

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Employee Checkin',
                filters: {
                    employee: frm.doc.employee,
                    time: ['between', [
                        frappe.datetime.get_today() + ' 00:00:00',
                        frappe.datetime.get_today() + ' 23:59:59'
                    ]]
                },
                fields: ['name', 'time', 'checkout_time']
            },
            callback: function(r) {

                if (r.message && r.message.length > 0) {

                    let existing = r.message[0];
                    frm.set_value('employee', '');

                    frappe.msgprint({
                        title: 'Already Checked In Today',
                        message:
                            `This employee already has a check-in record for today.<br><br>` +
                            `Check-in Time : <b>${existing.time}</b><br>` +
                            `Checkout Time : <b>${existing.checkout_time || 'Not yet checked out'}</b><br><br>` +
                            `<a href="/app/employee-checkin/${existing.name}" target="_blank">Open Existing Record</a>`,
                        indicator: 'red'
                    });
                }
            }
        });
    }

});

frappe.ui.form.on("Employee Checkin", {
    refresh(frm) {

        // run only for employee checkin screen
        if (!navigator.geolocation) {
            frappe.msgprint("Location not supported by browser");
            return;
        }

        navigator.geolocation.getCurrentPosition(function(position) {

            let lat = position.coords.latitude;
            let lng = position.coords.longitude;

            // If checkout time empty → checkin
            if (!frm.doc.checkout_time) {
                frm.set_value("latitude", lat);
                frm.set_value("longitude", lng);
            } 
            else {
                frm.set_value("latitude_out", lat);
                frm.set_value("longitude_out", lng);
            }

        });
    }
});

frappe.ui.form.on('Employee Checkin', {
    onload: function(frm) {
        // This sets the field to Read Only as soon as the form loads
        frm.set_df_property('employee', 'read_only', 1);

        if (frm.is_new()) {
            // Fetch the employee linked to the logged-in user
            frappe.db.get_value('Employee', {'user_id': frappe.session.user}, 'name', (r) => {
                if (r && r.name) {
                    frm.set_value('employee', r.name);
                }
            });
        }
    },
    refresh: function(frm) {
        // Secondary check to ensure it remains uneditable during refresh
        frm.set_df_property('employee', 'read_only', 1);
    }
});
